/* Original offline interaction prototype. No network, storage, Electron or OS access. */
(() => {
  'use strict';
  const $ = (s) => document.querySelector(s);
  const $$ = (s) => [...document.querySelectorAll(s)];
  const S = {lang:'zh',space:'task',kind:'task',converted:false,control:'human',generation:0,previous:null,scenario:'normal',tab:'notes',download:'running',cleanup:false,delivered:false,material:'',history:['https://research.example/fieldnotes'],historyIndex:0,spaces:{task:'',personal:'',empty:''},names:{task:'产品调研',personal:'个人阅读',empty:'待开始的空间'},timer:null};
  const l = (a,b) => S.lang === 'zh' ? a : b;
  const EN = {preview:'Browser design preview',layout:'Layout',theme:'Light / dark',long:'Long text',touch:'Touch',previewNote:'Offline · fictional pages and in-memory state · no websites, Obsidian or real Session verification',spaces:'Spaces',taskSpaces:'Task spaces',sharedSession:'Shared by you and Agent',emptySpace:'A fresh workspace',noPages:'No pages yet',personalSpaces:'Personal spaces',personalReading:'Personal reading',humanOnly:'Human only · no Agent access',spaceNote:'Separate spaces keep separate sign-ins. No Cookie copying within a space.',dataSettings:'Space & data',browser:'Browser',tabNotes:'Fieldnotes · Product notes',tabReference:'References',visit:'Go',pause:'Pause',siteTag:'Notes for thoughtful products',demoSite:'Fictional site',articleTitle:'Bring the work back to one page',articleIntro:'Keep the reading, unfinished notes and page context together. Hand over the work in front of you, not a separate copy.',updated:'Product notes · 2026 / 10 / 31',researchFocus:'Research focus',articleText:'Compare interactions and hierarchy. Record observations before choosing to send anything. Nothing on this screen is submitted automatically.',observation:'OBSERVATION',exampleText:'Put control status near the action. Make success, pause and unknown outcomes easy to distinguish.',sitePermission:'Simulate a location permission request',draftLabel:'Your page draft',notSubmitted:'Not submitted · memory only',saveDraft:'Save draft on the mock page',pageDisclaimer:'This is a fictional prototype page, not a webview, mirrored screenshot or website. These flows demonstrate interface states only.',startTitle:'Start with a page',startDesc:'Creating a space does not access the network. Open a page, then decide whether to hand it to an Agent.',openPage:'Open mock page',taskSummary:'CURRENT TASK',researchTask:'Collect product interaction notes',taskSummaryText:'HUHU Bot · one grant for this task space. Taking control stops the old task from reading or typing.',summaryLimit:'Check unknown outcomes before attempting anything again.',viewDetails:'View details',localPage:'Page owner: this workspace',footerNote:'Offline prototype · host capabilities not verified',scenarioTitle:'Interaction & failure scenarios',scenarioNote:'Review controls only — not part of the product UI.',scenario:'Scenario',simulateAgent:'Simulate Agent input',simulateLate:'Check old generation read',deleteSpace:'Simulate deleting space',reset:'Reset demo',scenarioInitial:'Type a draft, hand off, and take control. Check that the draft stays intact.'};
  const originalText = new Map($$('[data-i]').map(el=>[el,el.textContent]));
  function text(el,s){el.textContent=s;}
  function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function feedback(s,error=false){$('#feedback').hidden=false;$('#feedback').classList.toggle('error',error);text($('#feedback'),s);}
  function result(s){text($('#scenario-result'),s);}
  function row(a,b){return `<div class="detail-row"><span>${esc(a)}</span><span>${esc(b)}</span></div>`;}
  const dialog=$('#dialog');let opener=null;
  function close(){if(dialog.open)dialog.close(); if(opener?.isConnected)opener.focus();}
  function modal(title,body,actions){opener=document.activeElement;text($('#dialog-title'),title);$('#dialog-body').innerHTML=body;$('#dialog-actions').replaceChildren();for(const act of actions){const b=document.createElement('button');b.type='button';b.textContent=act.label;if(act.primary)b.className='primary';if(act.danger)b.className='danger';b.addEventListener('click',act.run);$('#dialog-actions').append(b);}if(!dialog.open)dialog.showModal();$('#dialog-close').focus();}
  $('#dialog-close').addEventListener('click',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
  function spaceName(){return S.lang==='en'?({task:'Product research',personal:'Personal reading',empty:'A fresh workspace'}[S.space]):S.names[S.space];}
  function humanLocked(){return S.control!=='human'||S.scenario!=='normal'||S.cleanup||S.space==='empty';}
  function update(){
    const descriptions={human:[l('由你操作','You are in control'),l('登录与操作留在同一页面，随时交接。','Keep sign-in and work on the same page. Hand off anytime.')],agent:[l('Agent 操作中','Agent in control'),l('你正在观察同一页面。接管会停止旧任务的读取与输入。','Watching the same page. Taking control stops the old task’s reads and input.')],revoking:[l('正在收回控制','Taking control'),l('等待撤权确认；确认前不开放人工输入。','Waiting for revocation acknowledgement before enabling input.')],paused:[l('Agent 已暂停','Agent paused'),l('旧授权已失效。继续前需重新交接。','The old grant is invalid. Hand off again to continue.')],unknown:[l('结果未知','Outcome unknown'),l('可能已提交；请先接管核对，不自动再次执行。','May already be submitted. Take control and check; no automatic replay.')]};
    const d=descriptions[S.control];text($('#control-status'),d[0]);text($('#summary-status'),d[0]);text($('#control-desc'),S.kind==='personal'?l('个人空间禁止 Agent 读取、截图和操作。','Agents cannot read, capture or operate personal spaces.'):d[1]);$('#control-status').className='badge '+(S.control==='agent'?'accent':S.control==='unknown'?'warning':'');
    text($('#current-space'),spaceName());text($('#primary-control'),S.kind==='personal'?l('转换为任务空间','Convert to task space'):S.control==='agent'||S.control==='revoking'||S.control==='unknown'?l('接管','Take control'):S.control==='paused'?l('重新交给 Agent','Hand off again'):l('交给 Agent','Hand to Agent'));
    $('#primary-control').disabled=S.control==='revoking'||S.cleanup||['unsupported','owner','crashed','loading','offline','error'].includes(S.scenario)||S.space==='empty';
    $('#pause').hidden=S.control!=='agent';$('#page-draft').disabled=humanLocked();$('#draft-form button').disabled=humanLocked();$('.site-button[data-act="permission"]').disabled=humanLocked();
    $('#address').disabled=humanLocked();$('#address-form button[type="submit"]').disabled=humanLocked();$('[data-act="reload"]').disabled=humanLocked();
    $('#back').disabled=humanLocked()||S.historyIndex===0;$('#forward').disabled=humanLocked()||S.historyIndex===S.history.length-1;
    $('#agent-action').disabled=S.control!=='agent'||S.scenario!=='normal'||S.kind==='personal'||S.cleanup;text($('#char-count'),String($('#page-draft').value.length));
    $$('.space-row[data-space]').forEach(el=>{el.classList.toggle('selected',el.dataset.space===S.space);el.setAttribute('aria-current',el.dataset.space===S.space?'true':'false');});
    $('#mock-page').hidden=S.space==='empty'||S.scenario!=='normal';$('#empty-page').hidden=S.space!=='empty';$('#state-page').hidden=S.scenario==='normal'||S.space==='empty';
    const states={loading:[l('正在加载页面','Loading page'),l('页面尚未就绪。取消后保留已有草稿。','Not ready yet. Cancelling preserves existing draft.'),l('取消加载','Cancel loading')],offline:[l('当前离线','You are offline'),l('草稿仍在；恢复连接前不会重放动作。','Your draft remains. No actions are replayed.'),l('模拟恢复连接','Simulate reconnect')],error:[l('页面无法打开','Page could not open'),l('没有改用另一个浏览器。检查地址后由你明确重试。','No fallback browser was started. Check the address, then retry explicitly.'),l('重试演示导航','Retry mock navigation')],crashed:[l('页面已崩溃','Page crashed'),l('Agent 授权已撤销。真实重载可能丢失页面内存与未保存输入。','Agent access is revoked. A real reload may lose page memory and unsaved input.'),l('确认重载演示页','Reload mock page')],owner:[l('此页面位于另一窗口','This page belongs to another window'),l('不创建副本。产品应前往原窗口；本原型只展示这条路径。','No duplicate page. The product should focus the owner; this demo shows the path only.'),l('演示前往所在窗口','Simulate focusing owner')],unsupported:[l('当前宿主能力不可用','Host capability unavailable'),l('不会下载 Chromium、启动 Native 或降低网页安全配置。','No Chromium download, Native runtime or security downgrade.'),l('查看诊断','View diagnostics')],unknown:[l('请先核对页面结果','Check what actually happened'),l('点击可能已发生。不要直接重试提交。','The click may already have happened. Do not repeat the submission.'),l('接管并核对','Take control and inspect')]};
    if(states[S.scenario]){const st=states[S.scenario];text($('#state-title'),st[0]);text($('#state-desc'),st[1]);text($('#state-action'),st[2]);}
    text($('#page-location'),S.scenario==='owner'?l('页面归属：另一工作台窗口','Page owner: another workspace window'):l('页面归属：当前工作台','Page owner: this workspace'));
  }
  function invalidate(control='human'){S.previous=S.generation;S.generation++;S.control=control;}
  function selectSpace(id){S.spaces[S.space+':'+S.tab]=$('#page-draft').value;invalidate();S.space=id;S.kind=id==='personal'&&!S.converted?'personal':'task';S.scenario='normal';S.cleanup=false;$('#scenario').value='normal';$('#page-draft').value=S.spaces[id+':'+S.tab]||'';$('#feedback').hidden=true;update();}
  function grant(){if(S.kind==='personal'){feedback(l('个人空间拒绝 Agent 访问。','Agent access to personal space denied.'),true);return;}
    modal(l('把当前任务空间交给 Agent','Hand this task space to Agent'),row(l('接收者','Recipient'),'HUHU Bot · '+l('产品调研任务','Product research'))+row(l('空间范围','Scope'),spaceName()+l(' · 此空间内页面',' · pages in this space'))+row(l('本次能力','Capabilities'),l('观察、截图、导航与结构化交互','Observe, screenshot, navigate, structured input'))+row(l('有效期','Lifetime'),l('本次任务；接管、暂停或退出即撤销','This task; revoked on takeover, pause or exit'))+`<div class="risk-note"><p>${esc(l('可见网页内容可能发送给所选 Agent / 模型。此空间中的登录态也可被用于网站操作。支付、发消息和上传仍需调用方单独审批。','Visible page content may reach the selected Agent/model. Signed-in access can be used on websites. Payments, messages and uploads still require separate caller approval.'))}</p></div>`,[{label:l('取消','Cancel'),run:close},{label:l('允许本次交接','Allow this handoff'),primary:true,run:()=>{S.previous=S.generation;S.generation++;S.control='agent';$('#page-draft').blur();close();update();feedback(l('演示授权已生效。你正在观察同一份原型页面草稿。','Mock grant active. You are watching the same prototype page draft.'));}}]);}
  function takeover(){if(S.control==='revoking')return;invalidate('revoking');update();result(l('演示：旧代次已经撤销，正在确认交接。','Demo: old generation revoked; awaiting acknowledgement.'));S.timer=setTimeout(()=>{S.timer=null;S.control='human';if(S.scenario==='unknown'){$('#scenario').value='normal';S.scenario='normal';}update();feedback(l('已接管。草稿保留；旧任务不能继续读取或输入。真实宿主屏障仍待验证。','Control returned. Draft preserved; old task cannot read or type. Real host fence remains unverified.'));},240);}
  function diagnostics(){modal(l('诊断与证据边界','Diagnostics & evidence boundary'),row(l('环境','Environment'),l('离线 HTML 原型；非 Obsidian','Offline HTML; not Obsidian'))+row(l('页面身份','Page identity'),'mock-page-'+S.space+'-'+S.tab)+row(l('控制代次（模拟）','Generation (mock)'),String(S.generation))+row(l('表面定案','Surface choice'),l('待 F01–F12 实测','Pending real F01–F12'))+`<p class="risk-note">${esc(l('未验证真实 Session、guest、权限、清理、跨平台或性能。本原型不读取 Cookie、文件、Obsidian 进程或网络。','No real Session, guest, permissions, cleanup, cross-platform or performance verification. This prototype reads no Cookies, files, Obsidian process or network.'))}</p>`,[{label:l('关闭','Close'),run:close}]);}
  function permission(){modal(l('网站请求定位权限','Site requests location'),row(l('来源','Origin'),'https://research.example')+row(l('页面范围','Frame'),l('当前页面 · 主 frame','Current page · main frame'))+`<p>${esc(l('仅允许这次请求。Agent 不能替你批准。这里不会调用设备定位。','Allow this request only. Agents cannot approve for you. No device location is accessed here.'))}</p>`,[{label:l('拒绝','Deny'),run:()=>{close();feedback(l('已拒绝此次定位请求。','Location request denied.'));}},{label:l('仅允许本次','Allow once'),primary:true,run:()=>{close();feedback(l('已记录演示的一次许可；未调用真实定位 API。','Mock one-time permission recorded; no real geolocation API called.'));}}]);}
  function dataSettings(){modal(l('空间与数据','Space & data'),`<p>${esc(l('网站登录数据由本机 Electron 管理，不随 Vault 自动同步。停用插件不等于清空登录态，卸载也不保证删除分区。','Website data is managed locally by Electron, not automatically synced with the Vault. Disabling or uninstalling is not equivalent to clearing sign-ins.'))}</p>`+row(l('当前空间','Current space'),spaceName())+`<p class="risk-note">${esc(l('旧 Native 浏览器数据默认保留且不读取。删除源码不代表删除用户文件。','Old Native browser data is retained and not read. Removing code does not delete user files.'))}</p>`,[{label:l('关闭','Close'),run:close},{label:l('查看删除范围','Review deletion scope'),run:deleteSpace}]);}
  function deleteSpace(){modal(l('删除这个空间？','Delete this space?'),row(l('将清理','Will clear'),l('此空间网站数据、页面目录、自有临时文件','This space’s site data, page list and owned temporary files'))+row(l('不会删除','Will not delete'),l('其他空间、Vault、系统浏览器、已导出文件','Other spaces, Vaults, system browsers, exported files'))+`<p class="risk-note">${esc(l('先撤权并关闭活动，再清理。失败必须保留清理状态；不承诺磁盘安全擦除。演示将故意进入 cleanup-pending。','Revoke and close activity before clearing. Failures must remain visible; no secure-erasure claim. This demo intentionally enters cleanup-pending.'))}</p>`,[{label:l('取消','Cancel'),run:close},{label:l('确认并演示删除','Confirm mock deletion'),danger:true,run:()=>{invalidate('paused');S.cleanup=true;close();update();feedback(l('清理未完成：模拟后台存储仍被占用。已禁止新操作，保留清理记录。','Cleanup pending: simulated background storage is busy. New operations blocked; cleanup record retained.'),true);modal(l('清理未完成','Cleanup pending'),`<p>${esc(l('此空间仍保留在列表中，不能导航或交给 Agent。重试只针对未完成步骤；不会删除其他空间或导出文件。','The space remains listed and cannot navigate or hand off. Retry only unfinished steps, never other spaces or exports.'))}</p>`,[{label:l('保留，稍后处理','Keep pending'),run:close},{label:l('演示重试成功','Simulate successful retry'),primary:true,run:()=>{S.cleanup=false;invalidate();S.space='empty';S.scenario='normal';close();update();feedback(l('演示清理完成。没有实际删除磁盘数据。','Mock cleanup completed. No disk data was deleted.'));}}]);}}]);}
  function downloads(){modal(l('下载','Downloads'),`<p>${esc(l('下载完成、导出和授权 Agent 读取是三个独立状态。以下是虚构文件。','Download completion, export and Agent read access are separate states. This file is fictional.'))}</p><div class="download-row"><div><strong>research-notes.pdf</strong><small>${esc(S.download==='running'?l('下载中 · 64% · 演示','Downloading · 64% · mock'):S.download==='cancelled'?l('已取消 · 部分文件待清理','Cancelled · partial file pending cleanup'):S.download==='failed'?l('下载失败 · 连接中断，残留可清理','Failed · connection lost; partial file owned'):l('下载完成 · 尚未授权读取','Complete · read access not granted'))}</small></div></div>`,S.download==='running'?[{label:l('演示下载失败','Simulate failure'),run:()=>{S.download='failed';downloads();}},{label:l('取消下载','Cancel download'),run:()=>{S.download='cancelled';close();feedback(l('演示下载已取消，部分文件由空间 owner 清理。','Mock download cancelled; the space owner handles partial cleanup.'));}},{label:l('演示下载完成','Simulate completion'),primary:true,run:()=>{S.download='completed';downloads();}}]:[{label:l('关闭','Close'),run:close}]);}
  function material(){const captured=$('#page-draft').value||l('观察：控制状态应靠近操作。','Observation: control status should sit near the action.');if(S.control!=='human'||S.cleanup||S.scenario!=='normal'){feedback(l('请先接管有效页面，再选择要交付的材料。','Take control of a valid page before choosing material.'),true);return;}
    modal(l('添加材料到输入框','Add material to an input'),`<p>${esc(l('仅添加到你选择的输入框，不会自动发送会话。','Adds to the chosen input only; never sends the conversation.'))}</p><label for="material-target">${esc(l('目标','Target'))}</label><select id="material-target"><option value="research">HUHU Bot · ${esc(l('调研对话','Research conversation'))}</option><option value="notes">${esc(l('另一个草稿输入框','Another draft input'))}</option></select><label>${esc(l('固定采集预览','Fixed capture preview'))}</label><div class="material-preview">${esc(captured)}</div><p class="mono">mock-page-${esc(S.space)}-${esc(S.tab)} · document-demo · research.example</p>`,[{label:l('取消','Cancel'),run:close},{label:S.delivered?l('查看已添加结果','View existing result'):l('添加，不发送','Add, do not send'),primary:true,run:()=>{const target=$('#material-target').selectedOptions[0].textContent;if(!S.delivered){S.material=captured;S.materialTarget=target;S.delivered=true;}close();modal(l('材料已在输入框，尚未发送','Material added, not sent'),row(l('已确认目标','Confirmed target'),S.materialTarget)+`<div class="material-preview">${esc(S.material)}</div><p>${esc(l('演示没有发送会话。交付结果未知时不会自动重复追加。','No conversation was sent. Unknown delivery results must not be appended again automatically.'))}</p>`,[{label:l('完成','Done'),run:close}]);}}]);}
  function nav(){modal(l('选择浏览空间','Choose a space'),`<div class="nav-sheet">${$('.side-section').outerHTML}${$$('.side-section')[1].outerHTML}</div>`,[{label:l('关闭','Close'),run:close}]);$('#dialog-body').querySelectorAll('[data-space]').forEach(b=>b.addEventListener('click',()=>{selectSpace(b.dataset.space);close();}));}
  const actions={
    'control':()=>{if(S.kind==='personal'){modal(l('转换为任务空间','Convert to task space'),`<p>${esc(l('此空间已登录的网站将可在你明确授权后供 Agent 使用。转换保持当前登录态，但本次转换不会自动授予控制权。','Signed-in websites become available after you explicitly grant Agent access. Conversion keeps this session, but does not automatically hand over control.'))}</p>`,[{label:l('取消','Cancel'),run:close},{label:l('转换，不授权','Convert, without granting'),primary:true,run:()=>{S.kind='task';S.converted=true;$('.sidebar .side-section').append($('.sidebar [data-space="personal"]'));$('.sidebar [data-space="personal"] small').textContent=l('已转换 · 任务空间','Converted · task space');invalidate();close();update();feedback(l('演示分类已转换；仍由你操作。需要再次明确交给 Agent。','Mock classification changed; you still control it. A separate handoff is required.'));}}]);}else if(['agent','unknown'].includes(S.control))takeover();else grant();},
    'pause':()=>{invalidate('paused');update();feedback(l('已暂停并撤销旧授权。可重新交给 Agent，或接管继续操作。','Paused; old access revoked. Hand off again or take control.'));modal(l('Agent 已暂停','Agent paused'),`<p>${esc(l('暂停不会关闭页面，也不会自动恢复旧队列。','Pausing keeps the page and never revives the old queue.'))}</p>`,[{label:l('保持暂停','Keep paused'),run:close},{label:l('由我继续','Continue myself'),primary:true,run:()=>{close();takeover();}}]);},
    'permission':permission,'downloads':downloads,'material':material,'delete-space':deleteSpace,'data-settings':dataSettings,'diagnostics':diagnostics,'navigation':nav,
    'create-space':()=>modal(l('新建空间','Create a space'),`<label for="new-name">${esc(l('空间名称','Name'))}</label><input id="new-name" maxlength="80" value="${esc(l('新的调研','New research'))}"><p>${esc(l('演示只创建一个空任务空间，不访问网络，也不自动授权。','The demo creates an empty task space; no network or automatic grant.'))}</p>`,[{label:l('取消','Cancel'),run:close},{label:l('创建演示空间','Create mock space'),primary:true,run:()=>{S.names.empty=$('#new-name').value.trim()||l('未命名空间','Untitled');selectSpace('empty');close();}}]),
    'open-page':()=>{selectSpace('task');feedback(l('已打开虚构页面；尚未授权 Agent。','Mock page opened; no Agent grant.'));},
    'new-page':()=>{if(S.control!=='human'||S.cleanup){feedback(l('请先接管再新建页面。','Take control before opening a page.'),true);return;}S.tab='reference';selectTab('reference');feedback(l('演示切到独立参考页。相同 URL 的新页不等于接管原页。','Switched to a separate mock reference tab. A new same-URL page is not the original page.'));},
    'reload':()=>{modal(l('重载页面？','Reload the page?'),`<p>${esc(l('真实重载会丢失未保存页面内存。演示确认后清空此页草稿，不重放 Agent 动作。','A real reload loses unsaved page memory. Confirming clears this mock draft, without replaying Agent actions.'))}</p>`,[{label:l('取消','Cancel'),run:close},{label:l('确认重载','Reload'),primary:true,run:()=>{$('#page-draft').value='';S.spaces[S.space+':'+S.tab]='';S.scenario='normal';$('#scenario').value='normal';invalidate();close();update();feedback(l('演示已重载；未自动恢复控制权。','Mock page reloaded; control not restored automatically.'));}}]);},
    'recover':()=>{if(S.scenario==='unsupported')diagnostics();else if(S.scenario==='unknown')takeover();else if(S.scenario==='crashed')actions.reload();else{S.scenario='normal';$('#scenario').value='normal';update();feedback(l('已返回演示页面；未执行任何真实窗口或网络操作。','Returned to the mock page; no real window or network action.'));}},
    'shell-info':()=>feedback(l('这是浏览器专项原型；其他工作台页面沿用总收口 change，不在此重做。','This prototype covers Browser only. Other pages belong to the shared design change.'))
  };
  $$('[data-act]').forEach(el=>el.addEventListener('click',()=>actions[el.dataset.act]?.()));
  $$('.sidebar [data-space]').forEach(el=>el.addEventListener('click',()=>selectSpace(el.dataset.space)));
  function selectTab(id){S.spaces[S.space+':'+S.tab]=$('#page-draft').value;S.tab=id;$('#page-draft').value=S.spaces[S.space+':'+S.tab]||'';update();$$('[data-tab]').forEach(el=>{const active=el.dataset.tab===id;el.classList.toggle('active',active);el.setAttribute('aria-selected',String(active));el.tabIndex=active?0:-1;});text($('[data-i="articleTitle"]'),id==='reference'?l('参考页与原页是不同的页面','A reference tab is a different page'):l('让工作回到同一个页面','Bring the work back to one page'));result(l('标签切换仅演示布局；原型草稿保持。真实 guest 身份需宿主验证。','Tab switch is a layout demonstration; prototype draft retained. Real guest identity needs host testing.'));}
  $$('[data-tab]').forEach((el,index)=>{el.addEventListener('click',()=>selectTab(el.dataset.tab));el.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[data-tab]');const idx=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[idx].dataset.tab);tabs[idx].focus();}});});
  $('#page-draft').addEventListener('input',()=>{S.spaces[S.space+':'+S.tab]=$('#page-draft').value;text($('#char-count'),String($('#page-draft').value.length));text($('#draft-state'),l('未提交 · 仅内存','Not submitted · memory only'));});
  $('#draft-form').addEventListener('submit',e=>{e.preventDefault();if(humanLocked())return;text($('#draft-state'),l('演示草稿已保存 · 不提交表单','Mock draft saved · no form submission'));});
  $('#address-form').addEventListener('submit',e=>{e.preventDefault();if(humanLocked())return;let value=$('#address').value.trim();try{const u=new URL(value);if(!['http:','https:'].includes(u.protocol))throw new Error();S.history=S.history.slice(0,S.historyIndex+1);S.history.push(u.href);S.historyIndex++;$('.address-field use').setAttribute('href',u.protocol==='https:'?'#i-lock':'#i-globe');$('.address-field').title=u.protocol==='https:'?'HTTPS':l('不安全 HTTP','Insecure HTTP');feedback(l('仅模拟地址变化，不访问网络：','Address changed in the demo only; no network: ')+u.origin+(u.protocol==='http:'?l(' · 不安全 HTTP',' · Insecure HTTP'):''));update();}catch{feedback(l('已拒绝不安全或无效地址。只演示 http/https，不导航到 file/javascript/data。','Unsafe or invalid address rejected. Only http/https is simulated; no file/javascript/data.'),true);}});
  $('#back').addEventListener('click',()=>{if(S.historyIndex>0){S.historyIndex--;$('#address').value=S.history[S.historyIndex];update();}});$('#forward').addEventListener('click',()=>{if(S.historyIndex<S.history.length-1){S.historyIndex++;$('#address').value=S.history[S.historyIndex];update();}});
  $('#agent-action').addEventListener('click',()=>{if(S.kind==='personal'||S.control!=='agent'||S.scenario!=='normal'||S.cleanup){result(l('拒绝：未获得有效任务空间授权。','Denied: no valid task space grant.'));return;}$('#page-draft').value+=l('\nAgent 草稿：保留控制状态，避免重复提交。','\nAgent note: keep control status visible; avoid duplicate submits.');S.spaces[S.space+':'+S.tab]=$('#page-draft').value;update();result(l('演示 Agent 在同一草稿元素上填写。没有真实 guest 输入。','Mock Agent wrote into the same draft element. No real guest input occurred.'));});
  $('#late-action').addEventListener('click',()=>{const stale=S.previous;const allowed=stale!==null&&stale===S.generation&&S.control==='agent'&&S.kind==='task'&&!S.cleanup;result(stale===null?l('尚无旧授权代次；先交接并接管。','No previous generation; hand off and take control first.'):allowed?l('检测到模拟错误：旧代次仍有效。','Mock error: old generation is still valid.'):l('旧代次请求已拒绝；不会返回页面文本或截图（内存模拟）。','Old-generation request denied; no page text or screenshot returned (in-memory simulation).'));});
  $('#scenario').addEventListener('change',e=>{S.scenario=e.target.value;if(S.scenario==='unknown')invalidate('unknown');else if(['crashed','unsupported','owner'].includes(S.scenario))invalidate('paused');else if(S.scenario==='normal'&&S.control==='paused')invalidate();update();});
  $('#reset').addEventListener('click',()=>{if(S.timer)clearTimeout(S.timer);S.timer=null;S.control='human';S.kind='task';S.converted=false;$$('.sidebar .side-section')[1].append($('.sidebar [data-space="personal"]'));$('.sidebar [data-space="personal"] small').textContent=l('仅人工 · Agent 不可访问','Human only · no Agent access');S.space='task';S.scenario='normal';S.cleanup=false;S.delivered=false;S.download='running';S.tab='notes';S.spaces={task:'',personal:'',empty:''};$('#page-draft').value='';$('#scenario').value='normal';$('#feedback').hidden=true;invalidate();update();result(l('演示已重置；没有清理真实数据。','Demo reset; no real data was cleared.'));});
  $('#theme').addEventListener('click',()=>document.documentElement.classList.toggle('dark'));
  $('#variant').value=document.body.dataset.variant;$('#variant').addEventListener('change',e=>{document.body.dataset.variant=e.target.value;});
  $('#touch').addEventListener('click',e=>{document.body.classList.toggle('touch');e.currentTarget.setAttribute('aria-pressed',String(document.body.classList.contains('touch')));});
  $('#long').addEventListener('click',e=>{const long=document.body.classList.toggle('long');e.currentTarget.setAttribute('aria-pressed',String(long));text($('#task-name'),long?l('这是一个很长的调研空间名称，用于检查窄窗口中的主操作可达性与布局稳定性','A very long product research workspace name for checking narrow layouts and reachable actions'):l('产品调研','Product research'));});
  $('#language').addEventListener('click',()=>{S.lang=S.lang==='zh'?'en':'zh';document.documentElement.lang=S.lang==='zh'?'zh-CN':'en';$$('[data-i]').forEach(el=>text(el,S.lang==='en'?EN[el.dataset.i]||originalText.get(el):originalText.get(el)));text($('#language'),S.lang==='zh'?'English':'中文');$('#page-draft').placeholder=l('在这里输入，接管前后草稿都会保留。','Type here. Your draft remains across handoff and takeover.');const vals=[['正常页面','Normal'],['加载中','Loading'],['离线','Offline'],['导航失败','Navigation error'],['页面崩溃','Page crashed'],['页面位于另一窗口','Owned by another window'],['宿主能力不支持','Unsupported host'],['已派发结果未知','Outcome unknown']];[...$('#scenario').options].forEach((o,i)=>o.textContent=vals[i][S.lang==='zh'?0:1]);update();});
  window.addEventListener('pagehide',()=>{if(S.timer)clearTimeout(S.timer);});
  update();
})();
